-- 속보이네: 2026-11-28 인기 제품 31종 2차 추가 (item_no 62~92)
-- 영양값: 식약처 품목제조보고·영양성분 공공데이터(100g당 × 총 내용량 환산). 라면 5종·짜요짜요는 제조사 표기값.
-- 원재료: 식약처 품목제조보고 신고 원재료(복합 구성품으로만 신고된 제품은 제조사 상품정보 고시 원재료명으로 보완).
-- data/products.js 와 같은 순서·값입니다. 여러 번 실행해도 안전(idempotent).
-- Supabase SQL Editor(프로젝트 nhdzexqkibotubfovbpa)에서 실행.

on conflict (id) do nothing;

-- 시퀀스를 최대 번호에 맞춘다 (다음 추가는 93번부터)
do $$
declare
  seq text := pg_get_serial_sequence('public.tumyeongbongji_products', 'item_no');
  mx integer;
begin
  select coalesce(max(item_no), 0) into mx from public.tumyeongbongji_products;
  if mx > 0 then
    perform setval(seq, mx, true);
  else
    perform setval(seq, 1, false);
  end if;
end $$;
